mapper.select:
select * from oj_personal_paper
user_id = #{userId}
order by create_time desc limit 1

select paper.create_time as paper_time, `count`, is_finish, (select count(*) from oj_paper_practice_theory where paper_id = paper.resource_id and solved = ${TRIED}) as wrong, (select count(*) from oj_paper_practice_theory where paper_id = paper.resource_id and solved = ${SOLVED}) as `right`, (select count(*) from oj_paper_practice_theory where paper_id = paper.resource_id and solved = ${NOT_START}) as not_start from oj_personal_paper as paper
user_id = #{userId}
order by paper.create_time desc
